-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION private.media_path_ok(p text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  select p is not null
    and length(p) between 3 and 512
    and position('/' in p) > 1
    and p !~ '^/' and p !~ '/$' and p !~ '//'
    and p !~ '(^|/)\.{1,2}(/|$)'
    and p !~ '[[:cntrl:]\\?#%]';
$function$;

